with base as (select id, customer_id, account_type, ceil(balance) as balance_whole, coalesce(status, 'NONE') as status_clean from accounts where status is not distinct from 'OPEN' and opened_date >= '2023-04-27') select s.id, s.customer_id, s.account_type, top1.amount, top1.transaction_txn_time from base s left join lateral (select c.amount, c.txn_time as transaction_txn_time from transactions c where c.account_id = s.id order by c.amount desc, c.id desc limit 1) top1 on true;
